window.MG_LAZY_DATA["data/lazy/courses/a004-f53aececf8f50238.json"]={sha256:"f53aececf8f50238fdfbd6c823cc4020a66fd36ba6b9c7c591a9f7cdcd864f0c",value:{"id":"a004","title":"晶圓研磨與拋光","titleEn":"Wafer lapping and polishing","category":"semiconductor","kind":"course","summary":"從鋸切晶圓的厚度與損傷開始，建立研磨、鏡面拋光、清潔與放行之間的證據鏈。","summaryEn":"Build an evidence chain from thickness and saw damage through lapping, mirror polishing, cleaning and release.","sourceIds":["v6-wafer-sumco","v6-cmp-applied","v3-media-80679a241086"],"status":"guided","contentStatus":"reviewable-educational-curriculum","depth":4,"stepCount":12,"estimatedMinutes":240,"languageCoverage":["zh-TW","en"],"diagram":{"type":"wafer","labels":["來料","研磨","損傷整備","鏡面拋光","清潔量測"],"labelsEn":["Incoming","Lapping","Damage preparation","Polishing","Clean and measure"],"original":true,"notToScale":true},"stages":[{"id":"a004-stage01","order":1,"title":"來料與幾何基準","titleEn":"Incoming material and geometry","description":"先辨認材料狀態與量測定義，再規劃可用的去除量。","descriptionEn":"Identify material condition and measurement definitions before allocating removal.","steps":[{"id":"a004-v6-01","order":1,"sequence":1,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco","v6-cmp-applied"],"prerequisiteIds":[],"title":"辨認裸矽晶圓與薄膜 CMP 的邊界","titleEn":"Distinguish bare-wafer finishing from film CMP","objective":"界定本批晶圓的材料層與後續用途。","objectiveEn":"Identify the material stack and intended next process.","instruction":"畫出鋸切裸矽與已有金屬圖案晶圓的兩種截面；在各截面標記可移除材料、保留材料及下一站需要的表面。比較兩者為何不能共用同一終點判據。","instructionEn":"Draw cross-sections of sawn bare silicon and a patterned metal wafer. Mark removable and retained material and the surface required next. Compare why the two need different endpoint criteria.","observation":"觀察「厚度達標」與「保留薄膜達標」是否指向不同的量測。","observationEn":"Notice whether target wafer thickness and target remaining film require different measurements.","failure":"若把金屬 CMP 的選擇性直接當成裸矽拋光規格，先退回材料清單重新界定。","failureEn":"If metal-CMP selectivity is treated as a bare-silicon specification, revisit the material inventory.","check":"交出兩張截面並為每張指定一項厚度和一項表面驗證。","checkEn":"Submit both cross-sections with one thickness and one surface check for each.","knowledge":[{"id":"a004-v6-01-k1","title":"加工對象","titleEn":"Processing target","text":"裸矽整備處理基板本體；薄膜 CMP 還須保護已形成的材料與圖案。","textEn":"Bare-wafer finishing shapes the substrate; film CMP must also preserve existing layers and patterns."},{"id":"a004-v6-01-k2","title":"終點的意義","titleEn":"Meaning of an endpoint","text":"停止條件取決於下一製程需求，不能只以外觀發亮決定。","textEn":"Stopping depends on the next process, not just a shiny appearance."}],"quiz":{"question":"兩片晶圓同樣發亮，為何仍不能用相同終點放行？","questionEn":"Why can two equally shiny wafers require different release endpoints?","options":["它們需要保留的材料和量測對象不同。","兩種終點都只由晶圓直徑決定。","只需反轉研磨方向，便可共用剩餘材料要求。"],"optionsEn":["They retain different materials and require different measurements.","Both endpoints depend only on wafer diameter.","Reversing polishing direction makes remaining-material requirements interchangeable."],"answer":0,"explanation":"它們需要保留的材料和量測對象不同。 裸矽整備處理基板本體；薄膜 CMP 還須保護已形成的材料與圖案。","explanationEn":"They retain different materials and require different measurements. Bare-wafer finishing shapes the substrate; film CMP must also preserve existing layers and patterns."}},{"id":"a004-v6-02","order":2,"sequence":2,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco"],"prerequisiteIds":["a004-v6-01"],"title":"建立厚度、彎曲與粗糙度量測圖","titleEn":"Map thickness, bow and roughness","objective":"把不同尺度的表面問題分開記錄。","objectiveEn":"Record surface problems at distinct spatial scales.","instruction":"在自行繪製的九點厚度表填入假設值並註明單位，計算最大與最小差值；另畫整片彎曲輪廓和局部粗糙度截線，避免把三種圖合成單一分數。","instructionEn":"Enter labeled hypothetical values in a nine-point thickness table and compute the maximum-minus-minimum difference. Separately sketch whole-wafer bow and local roughness rather than merging them into one score.","observation":"比較厚度一致但彎曲的晶圓，以及不彎曲但厚度不均的晶圓。","observationEn":"Compare a uniformly thick bowed wafer with a flat-looking wafer of uneven thickness.","failure":"若換夾持方式便改變結果，記錄支撐條件；不要把受力展平當成本體已修正。","failureEn":"If support changes the result, record the fixture condition; forced flattening is not permanent correction.","check":"清楚標明厚度差、整體形狀和局部表面三種證據的量測範圍。","checkEn":"Label the measurement extent of thickness variation, overall shape and local surface texture.","knowledge":[{"id":"a004-v6-02-k1","title":"空間尺度","titleEn":"Spatial scale","text":"平行度、整體形狀與局部粗糙度回答不同問題。","textEn":"Parallelism, overall shape and local roughness answer different questions."},{"id":"a004-v6-02-k2","title":"量測基準","titleEn":"Measurement reference","text":"夾持狀態、取樣位置和邊緣排除區須隨結果保存。","textEn":"Support condition, sampling positions and edge exclusion belong with the result."}],"quiz":{"question":"局部粗糙度降低，能否直接證明全片厚度更均勻？","questionEn":"Does lower local roughness prove improved full-wafer thickness uniformity?","options":["能，局部粗糙度就等於全片平行度。","不能，還需要厚度分布量測。","能，固定放大倍率已足以取代厚度取樣。"],"optionsEn":["Yes; local roughness is the same as full-wafer parallelism.","No; a thickness map is still required.","Yes; fixed magnification replaces thickness sampling."],"answer":1,"explanation":"不能，還需要厚度分布量測。 平行度、整體形狀與局部粗糙度回答不同問題。","explanationEn":"No; a thickness map is still required. Parallelism, overall shape and local roughness answer different questions."}},{"id":"a004-v6-03","order":3,"sequence":3,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco"],"prerequisiteIds":["a004-v6-02"],"title":"分配鋸切後的材料去除預算","titleEn":"Allocate removal after slicing","objective":"在厚度限制內保留後續整備的餘量。","objectiveEn":"Reserve finishing allowance within the thickness constraint.","instruction":"用紙上厚度帳本列出來料、研磨後、損傷去除後與拋光後四個狀態；自行設定教學數值並逐站相減，檢查最後仍留有修整餘量。","instructionEn":"Build a paper thickness ledger for incoming, lapped, damage-removed and polished states. Use explicitly hypothetical values, subtract each allowance and check that finishing margin remains.","observation":"比較平均厚度足夠但局部最薄點已不足的情況。","observationEn":"Compare an acceptable average thickness with an already insufficient local minimum.","failure":"若預算只用平均值，可能忽略最薄區；回到來料地圖調整分配。","failureEn":"An average-only budget can hide a thin region; revise the allocation using the incoming map.","check":"每一站的移除量與最薄位置均可追溯，且沒有負的剩餘餘量。","checkEn":"Trace every removal allocation and the thinnest location, with no negative remaining allowance.","knowledge":[{"id":"a004-v6-03-k1","title":"去除不可逆","titleEn":"Irreversible removal","text":"後段不能靠拋光補回已移除的矽。","textEn":"Later polishing cannot restore silicon already removed."},{"id":"a004-v6-03-k2","title":"最薄區控制","titleEn":"Minimum-thickness control","text":"放行需考慮局部限制，平均值只能作整體摘要。","textEn":"Local limits matter for release; the average is only a summary."}],"quiz":{"question":"平均厚度尚可，但一區已低於最終要求，應如何判斷？","questionEn":"The average is acceptable but one region is below the final requirement. What follows?","options":["只要中心點達標，其他位置可用平均值代替。","繼續全片均勻去除，直到最薄區回到厚度要求。","不能以平均值掩蓋局部不足，需重新判定可加工性。"],"optionsEn":["If the center passes, other locations may be replaced by the average.","Continue uniform removal until the thinnest region returns to the required thickness.","Reassess processability; the average cannot hide the local shortfall."],"answer":2,"explanation":"不能以平均值掩蓋局部不足，需重新判定可加工性。 後段不能靠拋光補回已移除的矽。","explanationEn":"Reassess processability; the average cannot hide the local shortfall. Later polishing cannot restore silicon already removed."}},{"id":"a004-v6-04","order":4,"sequence":4,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco"],"prerequisiteIds":["a004-v6-03"],"title":"檢查邊緣完整性與搬運接觸","titleEn":"Inspect edge integrity and handling contact","objective":"辨認可能形成碎屑或後續破片的邊緣狀況。","objectiveEn":"Recognize edge conditions that can generate debris or later fracture.","instruction":"在晶圓圓周示意圖標出缺角、裂紋與正常倒角，另畫載具接觸位置。比較缺陷是否靠近支撐點；只制定影像複查與隔離決策，不實作破壞試驗。","instructionEn":"Mark chips, cracks and normal bevels on an edge diagram, then add carrier contact locations. Compare defects with support points and define image review or quarantine decisions without destructive testing.","observation":"注意「平滑倒角」與不規則缺口的形狀差異，以及缺口附近的散落粒子。","observationEn":"Distinguish a smooth bevel from an irregular chip and look for nearby debris.","failure":"把正常倒角誤判為缺角會造成誤剔除；只看中心表面則可能漏掉裂紋。","failureEn":"Mistaking a bevel for a chip causes false rejects; viewing only the center can miss cracks.","check":"缺陷紀錄包含圓周位置、形貌與處置理由，而非只有合格勾選。","checkEn":"Record edge position, morphology and disposition reasoning rather than a pass check alone.","knowledge":[{"id":"a004-v6-04-k1","title":"邊緣應力","titleEn":"Edge stress","text":"邊緣形貌影響接觸與應力集中，也可能成為粒子來源。","textEn":"Edge geometry influences contact and stress concentration and can become a particle source."},{"id":"a004-v6-04-k2","title":"缺陷定位","titleEn":"Defect localization","text":"同一方位重複出現缺口可提示搬運或載具接觸問題。","textEn":"Repeated chips at the same orientation can suggest a handling or carrier-contact issue."}],"quiz":{"question":"缺口總在同一載具接觸附近出現，優先比較什麼？","questionEn":"Chips repeatedly occur near one carrier contact. What should be compared first?","options":["接觸位置與缺陷方位的關聯。","僅比較中心粗糙度，因為邊緣缺陷一定來自中心。","直接歸因於來料批次，不核對載具方位。"],"optionsEn":["The relationship between contact position and defect orientation.","Compare center roughness only, assuming every edge defect originates at the center.","Attribute it to incoming lots without checking carrier orientation."],"answer":0,"explanation":"接觸位置與缺陷方位的關聯。 邊緣形貌影響接觸與應力集中，也可能成為粒子來源。","explanationEn":"The relationship between contact position and defect orientation. Edge geometry influences contact and stress concentration and can become a particle source."}}]},{"id":"a004-stage02","order":2,"title":"研磨與表面整備","titleEn":"Lapping and surface preparation","description":"比較厚度修正、邊緣完整性與表面損傷，避免把粗加工當鏡面加工。","descriptionEn":"Separate thickness correction, edge integrity and damage removal from mirror finishing.","steps":[{"id":"a004-v6-05","order":1,"sequence":5,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco"],"prerequisiteIds":["a004-v6-04"],"title":"推演雙面研磨的厚度修正","titleEn":"Model thickness correction during lapping","objective":"理解兩面去除如何改善厚度與平行度。","objectiveEn":"Understand how removal from both faces changes thickness and parallelism.","instruction":"在截面模型將上、下研磨面分別標色，畫出厚端與薄端的去除趨勢。比較均勻去除和偏一側去除兩種假設，不把壓力示意值當作設備設定。","instructionEn":"Color the upper and lower lapping interfaces in a section model. Sketch removal trends at thick and thin regions and compare uniform versus one-sided removal assumptions without turning schematic pressure into machine settings.","observation":"觀察兩面總去除量相同時，偏斜是否仍可能殘留。","observationEn":"Check whether tilt can remain even when total removal from both faces is equal.","failure":"只追求總去除量會漏掉局部平行度；需返回厚度地圖，而非只看加工時間。","failureEn":"Total removal alone misses local parallelism; return to the thickness map rather than processing time.","check":"說明一個厚度改善但平行度未改善的案例。","checkEn":"Explain a case where thickness improves but parallelism does not.","knowledge":[{"id":"a004-v6-05-k1","title":"相對去除","titleEn":"Relative removal","text":"厚度與兩面相對形狀由材料去除的空間分布共同決定。","textEn":"Thickness and relative face shape depend on the spatial distribution of removal."},{"id":"a004-v6-05-k2","title":"時間不是品質","titleEn":"Time is not quality","text":"相同時間不保證相同去除分布，工具與接觸狀態也需追蹤。","textEn":"Equal time does not guarantee equal removal distribution; tool and contact condition also matter."}],"quiz":{"question":"研磨時間相同的兩批厚度分布不同，哪種說法較合理？","questionEn":"Two equally timed lots have different thickness maps. Which explanation is reasonable?","options":["相同時間必須對應相同去除，應先排除所有工具因素。","接觸與去除分布可能不同。","只要平均來料厚度相同，局部接觸就必然相同。"],"optionsEn":["Equal time requires equal removal, so all tool factors should be excluded.","Contact and removal distributions may differ.","Equal incoming average thickness guarantees identical local contact."],"answer":1,"explanation":"接觸與去除分布可能不同。 厚度與兩面相對形狀由材料去除的空間分布共同決定。","explanationEn":"Contact and removal distributions may differ. Thickness and relative face shape depend on the spatial distribution of removal."}},{"id":"a004-v6-06","order":2,"sequence":6,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco"],"prerequisiteIds":["a004-v6-05"],"title":"區分機械損傷去除與鏡面外觀","titleEn":"Separate damage removal from mirror appearance","objective":"把次表面損傷列為獨立整備問題。","objectiveEn":"Treat subsurface damage as a separate preparation concern.","instruction":"在鋸切與研磨後的剖面下方加上受損層，再畫去除後剖面。對照來源的加工順序，說明為何損傷整備不能僅由一張反光照片驗證；不配置蝕刻化學品。","instructionEn":"Add a damaged layer beneath sawn and lapped surfaces, then draw the section after its removal. Use the referenced sequence to explain why a reflective photograph cannot verify damage preparation; do not mix etchants.","observation":"觀察外觀粗糙度和損傷深度是否被誤畫為同一條界線。","observationEn":"Check whether surface roughness and damage depth have been incorrectly represented as the same boundary.","failure":"若以光澤代替損傷證據，列出仍未知的部分並保留待驗證狀態。","failureEn":"If gloss substitutes for damage evidence, list what remains unknown and keep the status unverified.","check":"在流程圖中標出損傷來源、去除目的及後續證據，沒有宣稱鏡面等於無損傷。","checkEn":"Mark the damage source, removal purpose and later evidence without equating a mirror finish with no damage.","knowledge":[{"id":"a004-v6-06-k1","title":"次表面層","titleEn":"Subsurface layer","text":"機械加工的影響可延伸到可見表面以下。","textEn":"Mechanical processing can affect material below the visible surface."},{"id":"a004-v6-06-k2","title":"證據範圍","titleEn":"Evidence scope","text":"外觀影像能說明可見缺陷，不能單獨涵蓋所有材料狀態。","textEn":"Appearance images show visible defects but cannot alone establish every material condition."}],"quiz":{"question":"晶圓很亮但沒有損傷去除紀錄，能否直接宣告無損傷？","questionEn":"A wafer is shiny but lacks damage-removal evidence. Can it be declared damage-free?","options":["能，鏡面粗糙度已完整代表次表面狀態。","能，研磨後平均厚度合格即代表所有損傷去除。","不能，外觀與材料損傷需要不同證據。"],"optionsEn":["Yes; mirror-surface roughness completely represents subsurface condition.","Yes; acceptable average thickness after lapping proves all damage was removed.","No; appearance and material damage require different evidence."],"answer":2,"explanation":"不能，外觀與材料損傷需要不同證據。 機械加工的影響可延伸到可見表面以下。","explanationEn":"No; appearance and material damage require different evidence. Mechanical processing can affect material below the visible surface."}},{"id":"a004-v6-07","order":3,"sequence":7,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco","v6-cmp-applied"],"prerequisiteIds":["a004-v6-06"],"title":"分解研磨墊、漿料與相對運動","titleEn":"Separate pad, slurry and relative motion","objective":"建立化學與機械作用共同去除材料的模型。","objectiveEn":"Model removal as coupled chemical and mechanical action.","instruction":"畫出晶圓、研磨墊與漿料三個界面，逐一改變示意中的接觸、供液或相對運動；在紙上預測哪種改變會造成去除變慢或局部不均。","instructionEn":"Draw wafer, pad and slurry interfaces. Change contact, liquid supply or relative motion one at a time in the sketch and predict slower removal or local nonuniformity.","observation":"比較材料容易反應但接觸不良，以及接觸充分但漿料狀態不合適的兩種情境。","observationEn":"Compare a reactive surface with poor contact against good contact with unsuitable slurry condition.","failure":"把所有變化歸因於轉速會忽略墊面或漿料；重新建立一因一變的比較。","failureEn":"Attributing every change to speed ignores the pad or slurry; restore a one-factor comparison.","check":"因果圖同時包含表面反應、接觸與帶走材料三條路徑。","checkEn":"Include surface reaction, contact and material removal pathways in the causal diagram.","knowledge":[{"id":"a004-v6-07-k1","title":"耦合作用","titleEn":"Coupled action","text":"CMP 同時依靠化學環境與機械接觸，不能僅視為乾磨。","textEn":"CMP couples a chemical environment with mechanical contact; it is not simply dry abrasion."},{"id":"a004-v6-07-k2","title":"變因隔離","titleEn":"Isolating variables","text":"一次比較一個變因，才容易判別局部不均的來源。","textEn":"Comparing one variable at a time helps identify the origin of nonuniformity."}],"quiz":{"question":"為何不能只提高轉速來解決每種拋光缺陷？","questionEn":"Why is increasing speed not a universal polishing fix?","options":["缺陷也可能來自接觸、墊面或漿料條件。","提高轉速會自動保持所有區域的接觸壓力一致。","所有缺陷都是去除量不足，延長加工即可解決。"],"optionsEn":["Defects can also arise from contact, pad condition or slurry.","Higher speed automatically equalizes pressure in every region.","Every defect is insufficient removal and can be fixed by longer processing."],"answer":0,"explanation":"缺陷也可能來自接觸、墊面或漿料條件。 CMP 同時依靠化學環境與機械接觸，不能僅視為乾磨。","explanationEn":"Defects can also arise from contact, pad condition or slurry. CMP couples a chemical environment with mechanical contact; it is not simply dry abrasion."}},{"id":"a004-v6-08","order":4,"sequence":8,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco","v6-cmp-applied"],"prerequisiteIds":["a004-v6-07"],"title":"追蹤工具狀態與批次漂移","titleEn":"Track tool condition and lot drift","objective":"把工具變化與晶圓差異分開比較。","objectiveEn":"Separate tool changes from wafer-to-wafer differences.","instruction":"自行建立三批假設紀錄，包含初始厚度、去除量與工具使用順序。將結果按時間與來料條件分別排序，判斷趨勢更像來料偏移還是工具狀態漂移。","instructionEn":"Create three hypothetical lots with starting thickness, removal and tool-use order. Sort results by time and incoming condition separately to distinguish material shift from tool-condition drift.","observation":"注意是否從某次工具狀態改變後，所有晶圓都出現相似偏移。","observationEn":"Look for a common shift across wafers after a tool-condition change.","failure":"混合不同來料規格可能製造假的時間趨勢；先分組再比較。","failureEn":"Mixing incoming specifications can create a false time trend; stratify before comparison.","check":"提出一項可區分兩種假說的追加觀察，並保留批次識別。","checkEn":"Propose an additional observation that distinguishes the hypotheses and retain lot identities.","knowledge":[{"id":"a004-v6-08-k1","title":"共同原因","titleEn":"Shared cause","text":"同一工具狀態可影響多片晶圓，因此需要批次與時間關聯。","textEn":"A shared tool condition can affect many wafers, making lot and time associations useful."},{"id":"a004-v6-08-k2","title":"分組比較","titleEn":"Stratified comparison","text":"相似來料的前後比較，比混合所有晶圓平均值更容易解讀。","textEn":"Before-and-after comparisons of similar inputs are easier to interpret than a mixed average."}],"quiz":{"question":"發現時間趨勢前，為何先確認來料規格一致？","questionEn":"Why check comparable incoming specifications before interpreting a time trend?","options":["因為不同來料只影響產量，從不影響去除結果。","避免把材料差異誤當成工具漂移。","因為分組後便不需要保留工具時間順序。"],"optionsEn":["Different incoming material affects output quantity but never removal results.","To avoid mistaking material differences for tool drift.","Stratification eliminates the need to retain tool-use order."],"answer":1,"explanation":"避免把材料差異誤當成工具漂移。 同一工具狀態可影響多片晶圓，因此需要批次與時間關聯。","explanationEn":"To avoid mistaking material differences for tool drift. A shared tool condition can affect many wafers, making lot and time associations useful."}}]},{"id":"a004-stage03","order":3,"title":"拋光與驗證","titleEn":"Polishing and verification","description":"以分布、缺陷與污染證據共同判定是否可交付下一製程。","descriptionEn":"Combine spatial profiles, defects and contamination evidence before release.","steps":[{"id":"a004-v6-09","order":1,"sequence":9,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-cmp-applied","v6-wafer-sumco"],"prerequisiteIds":["a004-v6-08"],"title":"評估中心與邊緣去除分布","titleEn":"Evaluate center-to-edge removal","objective":"以徑向地圖識別過度與不足去除。","objectiveEn":"Identify over-removal and under-removal on a radial map.","instruction":"將自己設定的拋光前後九點厚度相減，畫成中心、過渡區和邊緣三區。先描述哪區去除較多，再提出壓力或接觸假說；不替未知設備填入壓力數值。","instructionEn":"Subtract your hypothetical before-and-after nine-point maps and group removal into center, transition and edge. Describe the pattern before proposing pressure or contact hypotheses; do not invent machine pressures.","observation":"平均去除量相同的兩片，可能有相反的中心與邊緣分布。","observationEn":"Equal average removal can hide opposite center-to-edge patterns.","failure":"若只量中心，就無法確認邊緣過拋；補上邊緣取樣並標明排除範圍。","failureEn":"Center-only sampling misses edge overpolish; add edge sampling and label exclusions.","check":"交出分區去除圖及一個可被後續量測推翻的假說。","checkEn":"Submit a zonal removal map and a hypothesis that later measurements could disprove.","knowledge":[{"id":"a004-v6-09-k1","title":"分布回授","titleEn":"Profile feedback","text":"局部去除差異需要空間回授，單一平均厚度不足。","textEn":"Local removal differences need spatial feedback; one average thickness is insufficient."},{"id":"a004-v6-09-k2","title":"假說與觀察","titleEn":"Hypothesis versus observation","text":"「邊緣較薄」是觀察；「接觸壓力造成」仍需驗證。","textEn":"A thinner edge is an observation; a contact-pressure explanation still needs testing."}],"quiz":{"question":"平均去除達標但邊緣明顯過薄，應如何放行？","questionEn":"Average removal meets target but the edge is clearly too thin. How should release be judged?","options":["依平均值放行，局部不足可由中心厚度補償。","只重新定義排除區，不檢查這是否符合原規格。","依局部規格重新判定，不能只以平均值放行。"],"optionsEn":["Release by the average; center thickness compensates for a local deficit.","Redefine the excluded region without checking the original specification.","Reassess local specifications rather than release by the average alone."],"answer":2,"explanation":"依局部規格重新判定，不能只以平均值放行。 局部去除差異需要空間回授，單一平均厚度不足。","explanationEn":"Reassess local specifications rather than release by the average alone. Local removal differences need spatial feedback; one average thickness is insufficient."}},{"id":"a004-v6-10","order":2,"sequence":10,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco","v6-cmp-applied"],"prerequisiteIds":["a004-v6-09"],"title":"建立拋光終點與過拋辨識","titleEn":"Define a polishing endpoint","objective":"用目標剩餘量和缺陷條件共同決定停止。","objectiveEn":"Combine remaining-material targets and defect conditions when deciding to stop.","instruction":"在紙上比較提早停止、剛好達標及持續去除三個情境。為每一情境記錄剩餘厚度、均勻度和表面狀態；說明為何延長時間不能無限改善品質。","instructionEn":"Compare early stopping, target completion and continued removal on paper. Record remaining thickness, uniformity and surface condition for each, explaining why more time cannot improve quality indefinitely.","observation":"觀察缺陷改善與厚度損失可能同時發生，兩者需共同判讀。","observationEn":"Observe that defect improvement and thickness loss can occur together and must be interpreted jointly.","failure":"將時間到達視為唯一終點時，工具漂移會被漏掉；要求相應的量測佐證。","failureEn":"A time-only endpoint can miss tool drift; require matching measurement evidence.","check":"列出停止條件、超出條件與需要保留的驗證紀錄。","checkEn":"List stop criteria, out-of-limit conditions and the verification record to retain.","knowledge":[{"id":"a004-v6-10-k1","title":"多條件終點","titleEn":"Multiple endpoint conditions","text":"終點是符合要求的狀態，不只是計時器結束。","textEn":"An endpoint is a required state, not merely the end of a timer."},{"id":"a004-v6-10-k2","title":"過拋代價","titleEn":"Cost of overpolishing","text":"額外去除可能消耗幾何餘量，不能假定越久越好。","textEn":"Extra removal can consume geometric margin; longer is not automatically better."}],"quiz":{"question":"延長拋光使局部表面變好，卻低於厚度下限，結果為何？","questionEn":"Longer polishing improves a local surface but violates minimum thickness. What is the result?","options":["仍不符合整體放行要求。","表面要求優先時，厚度下限便自動失效。","用較低的平均去除率重算報告，就可視為沒有超限。"],"optionsEn":["It still fails the combined release requirements.","Giving surface quality priority automatically removes the thickness limit.","Recalculate the report with a lower average removal rate to erase the violation."],"answer":0,"explanation":"仍不符合整體放行要求。 終點是符合要求的狀態，不只是計時器結束。","explanationEn":"It still fails the combined release requirements. An endpoint is a required state, not merely the end of a timer."}},{"id":"a004-v6-11","order":3,"sequence":11,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco","v6-cmp-applied"],"prerequisiteIds":["a004-v6-10"],"title":"追蹤拋光後粒子與再污染","titleEn":"Trace particles and recontamination","objective":"區分去除缺陷與清潔後新增污染。","objectiveEn":"Distinguish polishing defects from contamination introduced after cleaning.","instruction":"畫出拋光出口、清洗、乾燥與載具四個交接點，為每點建立假設粒子位置圖。比較同一晶圓前後地圖，找出首次出現新粒子的交接位置。","instructionEn":"Draw handoffs from polishing to cleaning, drying and carrier storage. Create hypothetical particle maps at each and compare the same wafer over time to locate where new particles first appear.","observation":"查看粒子是否跟著固定方位、液滴痕跡或載具接觸分布出現。","observationEn":"Look for patterns tied to orientation, drying marks or carrier contacts.","failure":"最後一張地圖只能證明最終狀態，不能單獨證明哪個站點造成污染。","failureEn":"A final map establishes the final state but cannot alone identify the contaminating station.","check":"提出保留污染追溯能力的前後比對方案，不假定清洗必然成功。","checkEn":"Propose before-and-after comparisons that preserve traceability without assuming cleaning succeeded.","knowledge":[{"id":"a004-v6-11-k1","title":"交接污染","titleEn":"Handoff contamination","text":"已拋光表面仍可能在清潔與搬運之間重新受到污染。","textEn":"A polished surface can be recontaminated during cleaning and handling handoffs."},{"id":"a004-v6-11-k2","title":"同片追蹤","titleEn":"Same-wafer tracking","text":"同片同方位的比較有助於區別舊缺陷與新缺陷。","textEn":"Comparing the same wafer and orientation helps distinguish old and new defects."}],"quiz":{"question":"如何較有力地判斷污染是否在載具交接後出現？","questionEn":"What better supports a conclusion that contamination appeared after carrier handoff?","options":["比較不同批次的最終平均粒子數即可定位本站責任。","比較同一晶圓交接前後、相同方位的粒子圖。","只查看清洗設備的完成訊號即可排除搬運污染。"],"optionsEn":["Comparing final average particle counts from different lots identifies this station’s responsibility.","Compare aligned particle maps of the same wafer before and after handoff.","A cleaning-complete signal rules out handling contamination."],"answer":1,"explanation":"比較同一晶圓交接前後、相同方位的粒子圖。 已拋光表面仍可能在清潔與搬運之間重新受到污染。","explanationEn":"Compare aligned particle maps of the same wafer before and after handoff. A polished surface can be recontaminated during cleaning and handling handoffs."}},{"id":"a004-v6-12","order":4,"sequence":12,"estimatedMinutes":20,"simulationOnly":true,"sourceIds":["v6-wafer-sumco","v6-cmp-applied"],"prerequisiteIds":["a004-v6-11"],"title":"整合晶圓放行與異常處置","titleEn":"Integrate wafer release and disposition","objective":"用可追溯證據決定放行、複查或隔離。","objectiveEn":"Decide release, review or quarantine using traceable evidence.","instruction":"整理前十一項產物，將厚度、形狀、表面缺陷與清潔證據放在同一張放行表。加入一個缺少量測的案例及一個確認超限案例，分別說明下一個行動。","instructionEn":"Combine the prior outputs into a release sheet covering thickness, shape, surface defects and cleanliness. Add one missing-measurement case and one confirmed out-of-limit case and assign different next actions.","observation":"確認「尚無證據」沒有被寫成「已證明合格」，不同量測仍保留其基準。","observationEn":"Ensure missing evidence is not recorded as demonstrated compliance and each measurement retains its reference.","failure":"若重工會超出剩餘厚度預算，就不能僅因想降低報廢率而批准。","failureEn":"Do not authorize rework that exceeds the remaining thickness budget just to reduce rejects.","check":"每個結論都有批次、量測與處置理由，且下一站知道未解問題。","checkEn":"Link every conclusion to lot, measurement and disposition reasoning, with unresolved issues visible to the next stage.","knowledge":[{"id":"a004-v6-12-k1","title":"放行證據鏈","titleEn":"Release evidence chain","text":"產品放行需要相互一致的多項證據，而非挑選最漂亮的一項。","textEn":"Release needs consistent evidence across criteria, not selection of the most favorable result."},{"id":"a004-v6-12-k2","title":"重工可行性","titleEn":"Rework feasibility","text":"重工決策仍受材料餘量與缺陷機制限制。","textEn":"Rework remains constrained by material allowance and the defect mechanism."}],"quiz":{"question":"一項必要量測尚未取得時，正確狀態是什麼？","questionEn":"What status is appropriate when a required measurement is missing?","options":["直接合格，因為沒有超限數字。","用另一批的平均值補入，再視為本批已量測。","待驗證，先補齊證據再決定放行。"],"optionsEn":["Pass, because no out-of-limit number is present.","Fill in another lot’s average and treat this lot as measured.","Unverified; obtain the evidence before release."],"answer":2,"explanation":"待驗證，先補齊證據再決定放行。 產品放行需要相互一致的多項證據，而非挑選最漂亮的一項。","explanationEn":"Unverified; obtain the evidence before release. Release needs consistent evidence across criteria, not selection of the most favorable result."}}]}],"scope":"公開原理的十二項教學任務，以自行繪製的示意模型、試算及來源資料進行；未提供工廠實測資料、專有配方或設備操作許可。","scopeEn":"Twelve educational tasks based on public principles, using original schematic models, calculations and referenced material. No factory measurement dataset, proprietary recipe or equipment operating authorization is supplied.","curriculumVersion":6,"subcategory":"substrate","subcategoryTitle":"晶圓與基板","subcategoryTitleEn":"Wafers and substrates"}};
